(function(){
  var time=0;
  var colors=PALETTE;
  function cx(){return W()/2;}
  function cy(){return H()/2;}

  function hexToRgba(hex,a){
    var r=parseInt(hex.slice(1,3),16), g=parseInt(hex.slice(3,5),16), b=parseInt(hex.slice(5,7),16);
    return 'rgba('+r+','+g+','+b+','+a+')';
  }

  function pathPoint(s,t,ampScale){
    var x0=W()*0.08, y0=H()*0.92;
    var x1=W()*0.92, y1=H()*0.08;
    var x=x0+(x1-x0)*s;
    var y=y0+(y1-y0)*s;
    var dx=x1-x0, dy=y1-y0;
    var len=Math.hypot(dx,dy);
    var nx=-dy/len, ny=dx/len;
    var wave=Math.sin(s*Math.PI*6+t*0.6)*(30*ampScale);
    x+=nx*wave;
    y+=ny*wave;
    var ddx=x-cx(), ddy=y-cy();
    var dist=Math.hypot(ddx,ddy);
    var minDist=Math.min(W(),H())*0.24;
    if(dist<minDist){
      var push=(minDist-dist);
      var ang=Math.atan2(ddy,ddx);
      x+=Math.cos(ang)*push;
      y+=Math.sin(ang)*push;
    }
    return {x:x,y:y};
  }

  function drawFlute(t){
    var x0=W()*0.08, y0=H()*0.92;
    var ang=-0.55;
    var len=Math.min(W(),H())*0.36;
    var x1=x0+Math.cos(ang)*len;
    var y1=y0+Math.sin(ang)*len;
    ctx.save();
    ctx.lineCap='round';
    var pulse=0.5+0.5*Math.sin(t*0.8);
    ctx.strokeStyle=hexToRgba(colors[1],0.3+0.15*pulse);
    ctx.lineWidth=6;
    ctx.shadowBlur=14;
    ctx.shadowColor=colors[1];
    ctx.beginPath();
    ctx.moveTo(x0,y0);
    ctx.lineTo(x1,y1);
    ctx.stroke();
    ctx.shadowBlur=0;
    var holes=5;
    for(var i=1;i<=holes;i++){
      var s=i/(holes+1);
      var hx=x0+(x1-x0)*s;
      var hy=y0+(y1-y0)*s;
      ctx.beginPath();
      ctx.fillStyle=hexToRgba(colors[2],0.55);
      ctx.arc(hx,hy,3.5,0,Math.PI*2);
      ctx.fill();
    }
    ctx.restore();
  }

  var N=60;
  var notes=[];
  for(var i=0;i<N;i++){
    notes.push({
      s:Math.random(),
      speed:0.0012+Math.random()*0.0022,
      size:1.4+Math.random()*2.6,
      colorIdx:Math.floor(Math.random()*colors.length),
      trail:[]
    });
  }

  function draw(){
    time+=0.016;
    ctx.clearRect(0,0,W(),H());

    for(var k=0;k<3;k++){
      ctx.beginPath();
      var ampScale=0.5+k*0.35;
      for(var j=0;j<=110;j++){
        var s=j/110;
        var p=pathPoint(s,time+k*2.3,ampScale);
        if(j===0){ctx.moveTo(p.x,p.y);} else {ctx.lineTo(p.x,p.y);}
      }
      ctx.strokeStyle=hexToRgba(colors[k%colors.length],0.1+k*0.03);
      ctx.lineWidth=1+k*0.4;
      ctx.stroke();
    }

    for(var n=0;n<notes.length;n++){
      var note=notes[n];
      note.s+=note.speed;
      if(note.s>1.05){note.s-=1.05+Math.random()*0.1; note.trail=[];}
      var pt=pathPoint(note.s,time,1);
      note.trail.push({x:pt.x,y:pt.y});
      if(note.trail.length>12){note.trail.shift();}

      for(var tI=0;tI<note.trail.length;tI++){
        var tp=note.trail[tI];
        var alpha=(tI/note.trail.length)*0.45;
        ctx.beginPath();
        ctx.fillStyle=hexToRgba(colors[note.colorIdx],alpha);
        ctx.arc(tp.x,tp.y,note.size*(tI/note.trail.length),0,Math.PI*2);
        ctx.fill();
      }

      ctx.save();
      ctx.shadowBlur=10;
      ctx.shadowColor=colors[note.colorIdx];
      ctx.beginPath();
      ctx.fillStyle=hexToRgba(colors[note.colorIdx],0.85);
      ctx.arc(pt.x,pt.y,note.size,0,Math.PI*2);
      ctx.fill();
      ctx.restore();
    }

    drawFlute(time);

    requestAnimationFrame(draw);
  }

  requestAnimationFrame(draw);
})();
